#!/bin/bash
# SEARCH-ML job script - generated by searchml-hpc from hpc/templates/pbs.sh
# (resources are passed on the qsub command line; edit hpc/searchml-hpc.conf to change them)
set -uo pipefail
cd @@JOB_DIR@@ || exit 1
@@MODULE_LINE@@
if [ -n @@CONDA_BASE@@ ] && [ -f @@CONDA_BASE@@/etc/profile.d/conda.sh ]; then
  # shellcheck disable=SC1090
  source @@CONDA_BASE@@/etc/profile.d/conda.sh && conda activate @@CONDA_ENV@@
fi
export PATH=@@ENV_PREFIX@@/bin:$PATH
export AMBERHOME="${AMBERHOME:-@@ENV_PREFIX@@}"
export SEARCH_ML_HOME=@@SEARCH_ML_HOME@@
export SEARCHML_DATASETS=@@DATASETS_DIR@@
export SEARCHML_MODELS=@@MODELS_DIR@@
export SEARCHML_GZIP_MB=@@GZIP_MB@@
export SEARCHML_CPUS="${NCPUS:-${PBS_NUM_PPN:-@@CPUS@@}}"
export PYTHONUNBUFFERED=1
echo "SEARCH-ML job on $(hostname) | PBS job ${PBS_JOBID:-?} | CPUs $SEARCHML_CPUS | $(date)"
exec @@PYTHON@@ @@PIPELINE@@ run @@JOB_DIR@@ --quiet
